import assert from 'node:assert/strict';
import fs from 'node:fs';
import { execFileSync } from 'node:child_process';
import { createRequire } from 'node:module';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';
import { tmpdir, cpus } from 'node:os';
import { createHash } from 'node:crypto';
const repo = '/Users/mark/myown/interview';
const root = join(repo, 'ontology');
const require = createRequire(join(root, 'package.json'));
const { Client } = await import(pathToFileURL(require.resolve('@modelcontextprotocol/sdk/client/index.js')));
const { StdioClientTransport } = await import(pathToFileURL(require.resolve('@modelcontextprotocol/sdk/client/stdio.js')));
const { CallToolResultSchema } = await import(pathToFileURL(require.resolve('@modelcontextprotocol/sdk/types.js')));
const hash = bytes => createHash('sha256').update(bytes).digest('hex');
const sourceFiles = fs.readdirSync(join(root, 'src')).filter(file => file.endsWith('.mjs'));
const codeHashes = Object.fromEntries(sourceFiles.map(file => [file, hash(fs.readFileSync(join(root, 'src', file)))]));
const baselineSource = execFileSync('git', ['-C', repo, 'show', 'HEAD:ontology/src/snapshot.mjs']);
const baselineRevision = execFileSync('git', ['-C', repo, 'rev-parse', 'HEAD'], { encoding: 'utf8' }).trim();
const temporary = fs.realpathSync(fs.mkdtempSync(join(tmpdir(), 'ontology-mcp-before-')));
const connections = [];
try {
  fs.mkdirSync(join(temporary, 'src'));
  for (const file of sourceFiles) fs.copyFileSync(join(root, 'src', file), join(temporary, 'src', file));
  fs.writeFileSync(join(temporary, 'src/snapshot.mjs'), baselineSource);
  fs.copyFileSync(join(root, 'config.json'), join(temporary, 'config.json'));
  fs.symlinkSync(join(root, 'node_modules'), join(temporary, 'node_modules'));
  for (const cli of [join(temporary, 'src/cli.mjs'), join(root, 'src/cli.mjs')]) {
    const transport = new StdioClientTransport({ command: process.execPath,
      args: [cli, 'serve', '--repo', repo, '--committed-only'], stderr: 'pipe' });
    transport.stderr.on('data', chunk => process.stderr.write(chunk));
    const client = new Client({ name: 'snapshot-cache-benchmark', version: '1.0.0' });
    connections.push({ client, transport });
    await client.connect(transport);
  }
  const requests = [
    { query: 'Transactional Outbox', scope: ['tech'], max_bytes: 24000 },
    { query: '재시도 실패 중복 처리', scope: ['tech'], max_bytes: 24000 },
    { query: '온톨로지 조회 성능', scope: ['ontology'], max_bytes: 24000 },
  ];
  const call = async (which, args) => {
    const start = performance.now();
    const result = await connections[which].client.request({ method: 'tools/call',
      params: { name: 'context_lookup', arguments: args } }, CallToolResultSchema);
    const elapsed_ms = performance.now() - start;
    assert.ok(!result.isError, JSON.stringify(result.structuredContent));
    const payload = result.structuredContent;
    assert.equal(Buffer.byteLength(JSON.stringify(payload)), payload.budget.used_bytes);
    return { elapsed_ms, payload };
  };
  for (const request of requests) assert.deepEqual((await call(0, request)).payload, (await call(1, request)).payload);
  const rows = [];
  for (let round = 0; round < 5; round++) {
    for (let query = 0; query < requests.length; query++) {
      const output = {};
      const order = (round + query) % 2 ? [1, 0] : [0, 1];
      for (const which of order) output[which] = await call(which, requests[query]);
      assert.deepEqual(output[0].payload, output[1].payload);
      rows.push({ round, query, order, baseline_ms: output[0].elapsed_ms, current_ms: output[1].elapsed_ms,
        response_sha256: hash(JSON.stringify(output[0].payload)), bytes: output[0].payload.budget.used_bytes });
    }
  }
  for (const [file, sha] of Object.entries(codeHashes)) assert.equal(hash(fs.readFileSync(join(root, 'src', file))), sha, file);
  const quantile = (numbers, q) => numbers.toSorted((a,b)=>a-b)[Math.floor((numbers.length-1)*q)];
  const summary = field => ({ p50_ms: quantile(rows.map(r=>r[field]),0.5), p95_ms: quantile(rows.map(r=>r[field]),0.95) });
  const sample = (await call(1, requests[0])).payload;
  const report = { observed_at: new Date().toISOString(), environment: { node: process.version, platform: process.platform, arch: process.arch, cpu: cpus()[0].model },
    scope: 'Warm SDK stdio lookup, including freshness checks, verified snapshot loading, retrieval and local transport; excludes process startup and host reasoning. Three selected queries, five alternating rounds, one machine.',
    baseline_snapshot_revision: baselineRevision, baseline_snapshot_sha256: hash(baselineSource), code_sha256: codeHashes,
    snapshot: sample.index_sync[0], requests, pairs: rows.length, full_json_equivalence: true,
    summary: { baseline: summary('baseline_ms'), current: summary('current_ms') }, rows };
  fs.writeFileSync('/tmp/ontology-snapshot-mcp-performance-2026-09-08.json', JSON.stringify(report, null, 2) + '\n');
  console.log(JSON.stringify({ pairs: rows.length, summary: report.summary, full_json_equivalence: true }));
} finally {
  for (const connection of connections) await connection.transport.close();
  fs.rmSync(temporary, { recursive: true, force: true });
}
